        // ---------------- HAIR ----------------
        "hair_1" to Hi("बाल धुलाई की मूल बातें", "शैम्पू सिर्फ़ स्कैल्प पर लगाएं — तेल और धूल वहीं जमा होती है।", "स्कैल्प सीबम बनाता है जो बालों की लंबाई तक जाता है। उंगलियों से स्कैल्प की मसाज करने से तेल, पसीना और प्रोडक्ट की जमी गंदगी उतरती है; झाग नीचे बहकर लंबाई साफ़ कर देता है। कितनी बार धोएं — यह बालों के टाइप पर निर्भर है।", "अगली धुलाई में 60 सेकंड सिर्फ़ स्कैल्प की नरम मसाज करें।", "लंबाई को ज़ोर से रगड़ना — इससे क्यूटिकल खराब होती है और उलझन बढ़ती है।"),
        "hair_2" to Hi("सही शैम्पू कैसे चुनें", "शैम्पू अपने स्कैल्प के हिसाब से चुनें, बालों के सिरों के हिसाब से नहीं।", "शैम्पू का काम स्कैल्प साफ़ करना है। तैलीय स्कैल्प को हल्का या बैलेंसिंग फॉर्मूला अच्छा लगता है; रूखे या रूसी वाले स्कैल्प को नरम, मॉइस्चराइज़िंग वाला। सल्फेट-फ्री का मतलब हल्का झाग है — रूखे या कलर्ड बालों के लिए ठीक, पर जमी गंदगी के लिए कभी-कभी क्लैरिफाईंग वॉश भी चाहिए।", "अपने मौजूदा शैम्पू का लेबल पढ़ें और देखें कि वह आपके स्कैल्प टाइप से मेल खाता है या नहीं।", "सिर्फ़ मार्केटिंग शब्दों के चलते प्रोडक्ट लेना।"),
        "hair_3" to Hi("स्कैल्प केयर भी स्किन केयर है", "धोते समय स्कैल्प को नाखूनों से नहीं, उंगलियों से हल्की मसाज दें।", "स्कैल्प भी त्वचा ही है — स्वस्थ बाल स्वस्थ स्कैल्प से ही निकलते हैं। उंगलियों की धीमी मसाज खून का बहाव बढ़ाती है, रूसी हटाती है और मन को भी आराम देती है। नाखूनों से खुजलाने पर स्कैल्प पर छोटे घाव बन सकते हैं।", "अगली धुलाई में 2 मिनट स्कैल्प की धीमी गोलाई वाली मसाज करें।", "शैम्पू करते हुए नाखूनों से स्कैल्प खुरचना।"),
        "hair_4" to Hi("कंडीशनर सही तरीके से", "कंडीशनर लंबाई और सिरों पर लगाएं — जड़ों पर नहीं।", "कंडीशनर क्यूटिकल को चिकना करता है, रगड़ कम करता है और टूटन से बचाता है। जड़ों को इसकी ज़रूरत कम होती है क्योंकि स्कैल्प का तेल वहीं का वहीं नेचुरल कंडीशनर है। 1–3 मिनट छोड़कर हल्के ठंडे पानी से धोएं।", "अगली बार कंडीशनर बीच से सिरों तक लगाएं और 2 मिनट बाद धोएं।", "स्कैल्प पर कंडीशनर मलना — बाल भारी और चिपचिपे लगते हैं।"),
        "hair_5" to Hi("हीट स्टाइलिंग से बचाव", "ब्लो-ड्राय या स्ट्रैटनर से पहले हीट प्रोटेक्टेंट लगाएं और गर्मी एक नॉच कम रखें।", "बार-बार तेज़ गर्मी बालों की नमी चूस लेती है और क्यूटिकल धीरे-धीरे खराब होती है। हीट प्रोटेक्टेंट एक पतली परत बनाकर नुकसान घटाता है; मीडियम गर्मी भी काफ़ी होती है।", "आज हॉट टूल इस्तेमाल करें तो पहले प्रोटेक्टेंट लगाएं और सेटिंग एक डिग्री कम करें।", "गीले बालों पर सीधे स्ट्रैटनर चलाना — गीले बाल सबसे नाज़ुक होते हैं।", "अचानक बाल झड़ना, स्कैल्प पर घाव या बहुत ज़्यादा झड़न दिखे तो डर्मेटोलॉजिस्ट से मिलें।"),
        "hair_6" to Hi("नरम तरीके से उलझन खोलना", "उलझन सिरों से ऊपर की ओर, एक-एक हिस्से में खोलें।", "ऊपर से नीचे ज़ोर से कंघी मारने पर गांठों में खिंचाव लगता है और बाल टूटते हैं। सिरों से शुरू करके ऊपर बढ़ने से गांठें आसानी से खुलती हैं। गीले बालों में चौड़े दांतों वाली कंघी सबसे सुरक्षित है।", "आज बालों की उलझन सिरों से ऊपर की ओर खोलें।", "गीले बालों में ऊपर से ज़ोर से कंघी खींचना।"),
        "hair_7" to Hi("हफ़्ते भर की बाल केयर रूटीन", "ज़रूरत के हिसाब से धुलाई, हर बार कंडीशनर, हफ़्ते में एक मास्क।", "टिकाऊ रूटीन में दस प्रोडक्ट नहीं चाहिए — स्कैल्प के हिसाब से धुलाई, हर बार कंडीशनर, हफ़्ते में एक डीप कंडीशनिंग मास्क या तेल, और हीट स्टाइलिंग कभी-कभी। नियमितता ही असली फ़र्क़ लाती है।", "आज अपना हफ़्ते का बाल-प्लान लिखें: धुलाई के दिन, मास्क का दिन, हीट-फ्री दिन।", "हर हफ़्ते सारे प्रोडक्ट बदलना — बालों को बदलाव दिखाने में हफ़्ते लगते हैं।"),
        "hair_8" to Hi("तौलिये से नरम सुखाना", "गीले बालों को रगड़ने की जगह दबाकर और थपथपाकर सुखाएं।", "गीले बाल सबसे नाज़ुक होते हैं। खुरदरे तौलिये से ज़ोर से रगड़ने से क्यूटिकल खुलती है, रूखापन और फ्रिज़ बढ़ता है। नरम सूती कपड़े (पुरानी टी-शर्ट) से दबाकर सुखाना उतना ही आसान और कहीं बेहतर है।", "अगली बार बाल धोकर रगड़ने की जगह थपथपाकर सुखाएं।", "गीले बालों को खुरदरे तौलिये से ज़ोर-ज़ोर से पोंछना।"),

        // ---------------- SKIN ----------------
        "skin_1" to Hi("नरम क्लींज़िंग", "दिन में दो बार माइल्ड, pH-बैलेंस्ड फेस वॉश से चेहरा धोएं।", "क्लींज़िंग तेल, सनस्क्रीन, पसीना और प्रदूषण हटाती है। नरम क्लींज़र यह काम त्वचा की बैरियर लूटे बिना करता है। सख़्त साबुन और बहुत गर्म पानी नेचुरल तेल चटकर चेहरा दुखता-लाल छोड़ देते हैं।", "आज रात हल्के गुनगुने पानी से 60 सेकंड धोएं और थपथपाकर सुखाएं।", "चेहरे पर सख़्त साबुन या बहुत गर्म पानी इस्तेमाल करना।"),
        "skin_2" to Hi("गीली त्वचा पर मॉइस्चराइज़र", "चेहरा धोने के 2–3 मिनट के अंदर मॉइस्चराइज़र लगाएं।", "हल्की गीली त्वचा पर मॉइस्चराइज़र सबसे अच्छा काम करता है क्योंकि वह मौजूद पानी को सील कर देता है। मोटी क्रीम रूखी त्वचा के लिए, हल्का लोशन या जेल तैलीय त्वचा के लिए। तैलीय त्वचा को भी मॉइस्चराइज़र चाहिए।", "अगली धुलाई के तुरंत बाद, त्वचा गीली ही होते हुए मॉइस्चराइज़र लगाएं।", "तैलीय त्वचा में मॉइस्चराइज़र छोड़ना — पानी की कमी से तेल और बढ़ जाता है।"),
        "skin_3" to Hi("रोज़ सनस्क्रीन", "सनस्क्रीन त्वचा की सेहत और जवानी की सबसे असरदार आदत है।", "UV किरणें बादल वाले दिन और खिड़की के पास भी त्वचा को नुकसान पहुंचाती हैं। रोज़ ब्रॉड-स्पेक्ट्रम SPF 30+ लगाने से धूप से जलना, दाग़ और लंबे समय का नुकसान कम होता है। बाहर हों तो हर 2 घंटे में दोबारा लगाएं।", "आज सुबह SPF 30+ लगाएं — घर पर ही हों तब भी।", "सनस्क्रीन सिर्फ़ बीच या धूप वाले दिन लगाना।", "कोई तिल बदले या घाव जो भर न रहा हो — डर्मेटोलॉजिस्ट को दिखाएं।"),
        "skin_4" to Hi("प्रोडक्ट हाइजीन", "ब्रश हफ़्ते में एक बार धोएं; एक्सपायर प्रोडकट इस्तेमाल न करें।", "ब्रश, स्पंज और पफ़ में तेल, मृत त्वचा और बैक्टीरिया जमा होते हैं। साबुन से साप्ताहिक धुलाई दाने और इरिटेशन से बचाती है। ज़्यादातर प्रोडक्ट पर छोटा जार-चिन्ह होता है जो खोलने के बाद कितने महीने चलेंगे बताता है।", "आज सबसे ज़्यादा इस्तेमाल होने वाला ब्रश या स्पंज साबुन से धोकर सुखाएं।", "महीनों तक एक ही स्पंज बिना धुले चलाना।"),
        "skin_5" to Hi("गर्दन और डेकोलेताज", "स्किन केयर जबड़े पर न रुके — गर्दन तक ले जाएं।", "गर्दन और छाती की त्वचा पतली होती है और धूप उतनी ही लगती है। क्लींज़र, मॉइस्चराइज़र और सनस्क्रीन नीचे तक लगाने में सेकंड लगते हैं और सालों का फ़र्क़ दिखता है।", "आज मॉइस्चराइज़र और सनस्क्रीन गर्दन तक लगाएं।", "धोते समय गर्दन को नीचे की ओर ज़ोर से रगड़ना।"),
        "skin_6" to Hi("चेहरे को हाथ मत लगाएं", "बार-बार छूने और दाने मारने से बैक्टीरिया फैलता है और दाने बढ़ते हैं।", "दिनभर में हाथ दर्जनों चीज़ें छूते हैं। थप्पड़ टिकाना या दाने फोड़ने से बैक्टीरिया त्वचा में जाता है, सूजन बढ़ती है और दाने से बड़े निशान रह जाते हैं।", "आज हर बार ध्यान दें जब आप चेहरा छूती हैं — और नरमी से रुक जाएं।", "दाने फोड़ना या खुजलाना — निशान का ख़तरा बढ़ाता है।", "लगातार दर्दनाक मुंहासे डर्मेटोलॉजिस्ट के लायक हैं — अच्छा इलाज मौजूद है।"),
        "skin_7" to Hi("सोते वक़्त की लकीरें", "साफ़ सिल्क या सूती तकिया त्वचा और बालों दोनों के लिए बेहतर है।", "तकिए में तेल, मृत त्वचा और प्रोडक्ट जमा होते हैं। हफ़्ते में एक बार बदलना रात की स्किन-कॉन्टैक्ट साफ़ रखता है; मुलायम कपड़े से रगड़ कम लगती है।", "आज तकिये का कवर बदलें और कल त्वचा का एहसास देखें।", "हफ़्तों तक एक ही तकिये पर सोना।"),
