        // ---------------- ORAL ----------------
        "oral_1" to Hi("ब्रशिंग का सही तरीका", "दिन में दो बार, दो मिनट, नरम गोलाई वाली ब्रशिंग करें।", "प्लाक बैक्टीरिया की नरम परत है जो रोज़ जमती है। नरम ब्रश से धीमी गोलाई इसे एनामल और मसूड़ों को नुकसान दिए बिना हटा देती है। पूरे दो मिनट में हर दांत को समय मिलता है।", "आज रात टाइमर लगाकर पूरे दो नरम मिनट ब्रश करें।", "आरी की तरह ज़ोर से रगड़ना — एनामल और मसूड़े क्षतिग्रस्त होते हैं।"),
        "oral_2" to Hi("फ्लॉसिंग या इंटरडेंटल ब्रश", "दिन में एक बार दांतों के बीच साफ़ करें — ब्रश वहाँ नहीं पहुंचता।", "दांतों के बीच की जगह हर दांत की एक-तिहाई सतह छुपाती है जहाँ प्लाक से कैविटी और मसूड़ों की सूजन होती है। फ्लॉस या इंटरडेंटल ब्रश वहाँ पहुंचते हैं जहाँ ब्रश नहीं। अभ्यास से यह आसान हो जाता है।", "आज सारे दांतों के बीच फ्लॉस या इंटरडेंटल ब्रश करें।", "फ्लॉस को मसूड़ों पर चटका लगाकर उतारना — हर दांत की सतह पर धीरे से नीचे सरकाएं।"),
        "oral_3" to Hi("जीभ की सफ़ाई", "जीभ हल्के से साफ़ करें — सांस की बदबू का बड़ा कारण यहीं छिपा है।", "जीभ की खुरदरी सतह बैक्टीरिया और खाने के कण रोकती है। टंग क्लीनर या ब्रश से पीछे से आगे कुछ हल्के स्ट्रोक मुंह को ख़ुशबूदार रखते हैं।", "इस हफ़्ते रोज़ सुबह जीभ भी हल्के से साफ़ करें।", "इतनी ज़ोर से खुरचना कि जीभ दुखे या उबकाई आए — हल्का दबाव काफ़ी है।"),
        "oral_4" to Hi("ब्रश की हाइजीन और बदलाव", "ब्रश धोकर खड़ा रखें, हवा में सुखाएं, 3 महीने में बदलें।", "बंद डिब्बे में गीला ब्रश रखने पर बैक्टीरिया बढ़ते हैं। इस्तेमाल के बाद अच्छी तरह धोना, खड़ा करके हवा में सुखाना और 3 महीने में नया लेना (बीमारी के बाद भी) इसे सुरक्षित रखता है।", "आज अपना ब्रश देखें — ब्रिसल फैल गए हों तो नया ले लें।", "6 महीने से पुराना फैला हुआ ब्रश चलाना।"),
        "oral_5" to Hi("ब्रश कब करें", "खट्टे खान-पान के बाद 30 मिनट रुककर ब्रश करें।", "खट्टे फल, सोडा या शराब से एनामल थोड़ी देर के लिए नरम हो जाता है। तुरंत ब्रश करने पर यह नरम परत घिस जाती है। 30 मिनट रुकने पर लार एसिड संतुलित कर देती है।", "आज जूस या सोडा पीने के आधे घंटे बाद ब्रश करें।", "खट्टे खाने या उल्टी के तुरंत बाद ब्रश करना।"),
        "oral_6" to Hi("फ्लोराइड और डाइट", "फ्लोराइड टूथपेस्ट एनामल मज़बूत करता है; बीच-बीच में मीठा खाना कैविटी को ईंधन देता है।", "फ्लोराइड एनामल को दोबारा मिनरल देता है — दुनिया भर के डेंटल संगठन इसे मान्य करते हैं। दिनभर थोड़ा-थोड़ा मीठा खाने से कैविटी बैक्टीरिया को लगातार खाना मिलता है; मिठाई को खाने के साथ रखना ही बेहतर है।", "आज फ्लोराइड टूथपेस्ट से ब्रश करें और मीठे ड्रिंक एक ही बार में पूरे करें।", "घंटों चूसते हुए मीठा पीना।"),
        "oral_7" to Hi("ताज़ी सांस की मूल बातें", "लगातार बदबू ज़्यादातर जीभ, सूखा मुंह और कम सफ़ाई से आती है।", "पानी पीते रहना, रोज़ जीभ साफ़ करना और दिन में दो बार ब्रश — रोज़मर्रा की बदबू का ज़्यादातर हिस्सा यहीं ख़त्म हो जाता है। लहसुन-प्याज़ की बदबू अस्थायी होती है; बैक्टीरिया से आने वाली बदबू लगातार होती है।", "आज नियमित पानी पिएं और रात जीभ साफ़ करें।", "बदबू को मिंट से ढकने की जगह वजह हटाना।"),
        "oral_8" to Hi("नियमित डेंटल चेकअप", "6–12 महीने में एक बार प्रोफेशनल क्लीनिंग और जांच — दिक्कत छोटी ही पकड़ में आती है।", "टार्टर (कठित प्लाक) घर पर ब्रश से नहीं उतरता। प्रोफेशनल क्लीनिंग उसे हटाती है और शुरुआती कैविटी या मसूड़ों की दिक्कत छोटी अवस्था में इलाज आसान और सस्ता होता है।", "आज अपना अगला डेंटल अपॉइंटमेंट बुक करें या नोट करें।", "दर्द होने पर ही डेंटिस्ट जाना।", "मसूड़ों से खून, ढीले दांत या लगातार घाव — डेंटिस्ट को ज़रूर दिखाएं।"),

        // ---------------- BODY ----------------
        "body_1" to Hi("नहाने की आदतें", "दिन में एक बार गुनगुने पानी और नरम साबुन से नहाना काफ़ी है।", "बहुत गर्म पानी और सख़्त साबुन त्वचा की सुरक्षा-परत का तेल चटकर रूखेपन और खुजली छोड़ते हैं। गुनगुना पानी और माइल्ड क्लींज़र भी साफ़ करते हैं, बिना बैरियर तोड़े।", "अगली बार गुनगुने पानी से 10–15 मिनट से कम नहाएं।", "घंटों का बहुत गर्म शावर और तेज़ खुशबू वाले साबुन।"),
        "body_2" to Hi("नहाने के बाद मॉइस्चराइज़र", "तौलिये से पोंछने के 3 मिनट के अंदर बॉडी लोशन लगाएं।", "नहाने के तुरंत बाद त्वचा में पानी भरा होता है; मॉइस्चराइज़र उस पानी को उड़ने से पहले सील कर देता है। यह एक छोटी आदत खुजली और खिंचाव से बचाती है — सर्दियों में ख़ासकर।", "लोशन को तौलिये के पास रखें और अगली बार नहाने के तुरंत बाद लगाएं।", "पूरी सूखकर, बाद में याद आने पर लोशन लगाना।"),
        "body_3" to Hi("हाथों की सफ़ाई", "दिन के ज़रूरी पलों में 20 सेकंड साबुन से हाथ धोएं।", "हाथ ही गेर्म्स को चेहरे और खाने तक ले जाते हैं। ज़रूरी पल: शौच के बाद, खाने से पहले, घर आकर, और छींक-खांसी के बाद। 20 सेकंड का झाग — कोई भी पसंदीदा गाना दो बार गुनगुनाने जितना।", "अगली बार पूरे 20 सेकंड गिनकर हाथ धोएं।", "3 सेकंड की झटपट धुलाई या ऐसे साबुन जिनसे हाथ फटते हैं।"),
        "body_4" to Hi("कपड़ों की हाइजीन", "पसीना छूने वाले कपड़े रोज़ बदलें — अंदर के और मोज़े।", "पसीना और त्वचा के बैक्टीरिया कपड़ों में जमा होते हैं। रोज़ ताज़े अंडरगारमेंट्स और मोज़े, और हर वर्कआउट के बाद धुले कपड़े — बदबू, इरिटेशन और त्वचा की दिक्कतों से बचाते हैं। जींस-स्वेटर कई बार चल सकते हैं; शरीर से चिपके कपड़े नहीं।", "आज की लॉन्ड्री अलग करें: जो शरीर से छूकर आया है, उसे धोना है।", "पसीने से भीगे वर्कआउट कपड़े या मोज़े दोबारा पहनना।"),
        "body_5" to Hi("त्वचा की सिलवटों की देखभाल", "शरीर की सिलवटों को साफ़ और पूरी तरह सूखा रखें।", "छाती के नीचे, पेट की लाइन और जांघों के बीच जैसी जगहों में नमी और गर्मी फंसती है जिससे त्वचा चिढ़ जाती है। नरम सफ़ाई, अच्छा धोना और पूरी सुखाई (ठंडी हवा का फ़ॉइन चला लें) आराम रखती है।", "अगली बार नहाने के बाद सिलवटों को एक पल अलग से पूरा सूखा करें।", "सिलवटों में मलममल ताल्क झोंकना या ज़ोर से रगड़ना।"),
        "body_6" to Hi("तौलिये और नहाने के कपड़े", "बॉडी टॉवल 3–4 इस्तेमाल बाद बदलें और पूरा फैलाकर सुखाएं।", "गीले तौलिये में बैक्टीरिया बढ़ते हैं और बासी गंध आती है। इस्तेमाल के बीच फैलाकर सुखाना और कुछ दिन में धोना त्वचा के संपर्क को साफ़ रखता है। परिवार में भी तौलिये साझा न करें।", "आज देखें आपका तौलिया कब से नहीं धुला — ज़रूरत हो तो बदलें।", "चेहरे और शरीर का एक ही तौलिया या साझा तौलिया।"),
        "body_7" to Hi("रोज़ की तराशता रूटीन", "सुबह की सिंपल रूटीन: धोना, डिओडरेंट, ताज़े कपड़े।", "बदबू पसीने से नहीं, पसीने को तोड़ने वाले बैक्टीरिया से आती है। मुख्य जगहें धोना, साफ़-सूखी त्वचा पर डिओडरेंट और ताज़े कपड़े — बस इतना ही काफ़ी है।", "आज सुबह साफ़, सूखी त्वचा पर डिओडरेंट लगाएं।", "बिना धोए कल के ऊपर डिओडरेंट की परत।"),
        "body_8" to Hi("अपनी त्वचा की आवाज़ सुनें", "लगातार खुजली, रैश या कोई अजीब बदलाव — विशेषज्ञ की नज़र चाहिए।", "कभी-कभी रूखेपन या इरिटेशन सबको होता है। पर फैलता रैश, रुकने वाली न रुकने वाली खुजली, या तिल/घाव में अचानक बदलाव — ये त्वचा के विशेषज्ञ को दिखाने के संकेत हैं; घरेलू नुस्ख़े इनका इलाज नहीं।", "आज 1 मिनट का त्वचा-चेक करें — आगे-पीछे।", "रहने वाली स्टेरॉयड क्रीम से खुद इलाज करना।", "फैलता रैश, न भरते घाव या बदलते तिल — डॉक्टर या डर्मेटोलॉजिस्ट से मिलें।"),

        // ---------------- NAILS ----------------
        "nails_1" to Hi("नाखून काटने का सही तरीका", "नाखून सीधे काटें, कोनों को हल्का गोल करें — अंदर उगने से बचाव।", "बहुत छोटे या कोनों में गहरे काटने से आसपास की त्वचा नाखून पर चढ़ जाती है और नाखून उसमें घुसता — दर्दनाक और इन्फेक्शन का ख़तरा। सीधा काटना और हल्के गोल कोने सबसे सुरक्षित हैं, पैरों के नाखूनों के लिए ख़ासकर।", "आज नाखून सीधे काटें — बहुत छोटे नहीं।", "पैर के नाखूनों के कोनों को गहरा गोल काटना।"),
        "nails_2" to Hi("नाखूनों के नीचे की सफ़ाई", "रोज़ हल्की सफ़ाई से छिपी गंदगी और बैक्टीरिया दूर रहते हैं।", "नाखूनों के नीचे दिनभर की गंदगी जमा होती है। नरम ब्रश या हाथ धोते समय साबुनी हथेली पर नाखून रगड़ना काफ़ी है। नुकीली धातु से खुदाई नाखून को त्वचा से अलग कर सकती है।", "आज हर बार हाथ धोते समय नाखूनों को साबुनी हथेली पर रगड़ें।", "नुकीले धातू औज़ार से नीचे खुदाई करना।"),
        "nails_3" to Hi("क्यूटिकल की देखभाल", "क्यूटिकल काटें नहीं — नरम करके हल्के से पीछे धकेलें।", "क्यूटिकल नाखून की त्वचा को बैक्टीरिया और फंगस से बचाने वाली मुहर है। उसे काटना यह मुहर हटाता है — इन्फेक्शन का आम रास्ता। नहाने के बाद तेल लगाकर साफ़ औज़ार से हल्का पीछे धकेलना काफ़ी है।", "आज रात क्यूटिकल्स में एक बूंद तेल मलें।", "क्यूटिकल काटना या दांतों से खुरचना।", "नाखून के आसपास लाली, सूजन या मवाद — डॉक्टर को दिखाएं।"),
        "nails_4" to Hi("मेनीक्योर के बीच नाखून हाइजीन", "नाखूनों को नम-मॉइस्चराइज़्ड रखें और पॉलिश को कभी-कभी आराम दें।", "लगातार पॉलिश और जेल नाखूनों को रूखा-भुरभुरा बनाते हैं। हफ़्ते में एक ब्रेक, नाखूनों में हैंडक्रीम और बर्तन-सफ़ाई में दस्ताने — नाखून भी सुरक्षित रहते हैं, आसपास की त्वचा भी।", "आज बर्तन या सफ़ाई के किसी काम में दस्ताने पहनें।", "जेल पॉलिश को खींचकर/छीलकर उतारना — नाखून की परत भी साथ आती है।"),
        "nails_5" to Hi("फाइल करें, खींचें नहीं", "कच्चे किनारों को फाइल से सीधा करें — तोड़ें या काटें नहीं।", "अटके नाखून को हाथ से तोड़ने या दांतों से काटने पर नाखून की परतें अंदर तक फटती हैं — टूटन बड़ा और उगाव टेढ़ा होता है। बारीक फाइल एक ही दिशा में चलाना सुरक्षित है।", "आज जेब में/बैग में एक नेल फाइल रखें और कच्चे किनारे पर इस्तेमाल करें।", "नाखून चबाना या अटके हिस्से को उंगलियों से फाड़ना।"),
        "nails_6" to Hi("पैर के नाखून", "नहाने के बाद नाखून नरम होते हैं — तब काटें, और बहुत छोटे नहीं।", "नरम नाखून साफ़-सीधे कटते हैं। थोड़ी लंबाई छोड़ना कोनों में त्वचा में उगने से बचाता है। सही नाप के जूते भी ज़रूरी हैं — टांगे हुए पंजे नाखूनों की दिक्कत का आम कारण हैं।", "आज देखें कि जूते में पंजों को हिलने की जगह है या नहीं।", "पैर के नाखून बहुत छोटे और गहरे गोल काटना।", "पैर का नाखून दर्दनाक, लाल या सूजन वाला हो तो विशेषज्ञ को दिखाएं।"),
        "nails_7" to Hi("औज़ार और साझेदारी", "नाखून के औज़ार साफ़ रखें और कभी साझा न करें।", "नेल टूल्स त्वचा को छूते हैं और लोगों के बीच — या आपके ही हाथ-पैर के बीच — बैक्टीरिया और फंगस ढो सकते हैं। कैंची-फाइल को कभी-कभी अल्कोहल से पोंछना और अपना अलग सेट रखना हाइजीनिक है।", "आज अपने नेल क्लिपर को रबिंग अल्कोहल से पोंछ दें।", "परिवार में क्लिपर या फाइल साझा करना।"),
        "nails_8" to Hi("स्वस्थ नाखून कैसे दिखते हैं", "नाखूनों पर रेखाएं-धब्बे आम हैं — ज़्यादातर निशान बेकार की चिंता नहीं।", "छोटे सफ़ेद धब्बे आमतौर पर हल्की चोट से होते हैं और उम्र के साथ हल्की खड़ी रेखाएं भी सामान्य हैं। असली चेतावनी हैं: लगातार रंग बदलना, मोटा होना, या नाखून का त्वचा से उठना — ये डॉक्टर को दिखाने लायक हैं।", "आज अपने नाखूनों को शांति से, बिना आलोचना के देखें।", "हर मामूली धब्बे को बड़ी बीमारी समझकर घबराना।", "लगातार रंग बदलना, मोटापन या त्वचा से अलग होता नाखून — डॉक्टर को दिखाएं।"),

        // ---------------- FEET ----------------
        "feet_1" to Hi("पैरों को ठीक से धोना", "नहाते समय पैरों को साबुन से धोएं — बस पानी बहा देना काफ़ी नहीं।", "पैर पूरे दिन पसीना और बैक्टीरिया जमा करते हैं। चलता पानी उन्हें नहीं हटाता। 30 सेकंड की साबुन वाली धुलाई — ख़ासकर उंगलियों के बीच — बदबू और फंगल दिक्कतों से बचाती है।", "अगली बार नहाते समय पैरों को अच्छी तरह, उंगलियों के बीच सहित धोएं।", "पैरों पर बहते साबुन को ही ‘धुलाई’ मान लेना।"),
        "feet_2" to Hi("उंगलियों के बीच सुखाना", "नहाने के बाद उंगलियों के बीच पूरा सुखाएं।", "उंगलियों के बीच की नमी फंगस (एथलीट फुट) का पसंदीदा घर है। तौलिये से थपथपाकर सुखाने में सेकंड लगते हैं और हफ़्तों की खुजली टलती है।", "अगली बार नहाने के बाद हर उंगली के बीच अलग से सुखाएं।", "हल्की गीली उंगलियों पर मोज़े पहन लेना।"),
        "feet_3" to Hi("पैरों में मॉइस्चराइज़र", "एड़ियों-तलवों में रोज़ क्रीम; उंगलियों के बीच नहीं।", "तलवों में तेल ग्रंथियां नहीं होतीं, इसलिए वे फटते हैं — रोज़ क्रीम उन्हें मुलायम रखती है। पर उंगलियों के बीच क्रीम लगाने से वहाँ नापसंद नमी बढ़ती है; वहाँ त्वचा सूखी रहने दें।", "आज रात एड़ियों और तलवों में फुट क्रीम लगाएं।", "उंगलियों के बीच मोटी क्रीम लगाना।"),
        "feet_4" to Hi("जूतों की हाइजीन", "जूते बदल-बदल कर पहनें — 24–48 घंटे सुखने दें।", "जूते पसीना सोखते हैं और पूरा सूखने में एक-दो दिन चाहिए। रोज़ एक ही जोड़ी पहनने पर वह गीली रहती है — बदबू और फंगस का न्योता। दो जोड़ी बदलकर और सांस लेने वाले मोज़े काफ़ी फ़र्क़ लाते हैं।", "आज अपने जूतों को हवा लगाएं और इनसोल देखें।", "एक ही बंद जूती रोज़-रोज़ पहनना।"),
        "feet_5" to Hi("मोज़ों का बड़प्पन", "रोज़ ताज़े, फिट वाले मोज़े; सूती/ऊनी सबसे आरामदायक।", "मोज़े दिनभर त्वचा से चिपके रहते हैं — 12+ घंटे। रोज़ नए मोज़े, बिना दबाव वाली सिलाई और सांस लेने वाला कपड़ा पैरों को सूखा रखता है।", "आज ताज़े मोज़े पहनें और फ़र्क़ महसूस करें।", "पुराने या पसीने में भीगे मोज़े दोहराना।"),
        "feet_6" to Hi("एड़ियों की नरम देखभाल", "रूखी एड़ियों के लिए मॉइस्चराइज़िंग क्रीम — खुरचने से बचें।", "कॉर्न/मोटी त्वचा दबाव का नतीजा है। ज़ोर से रगड़ना या ब्लेड चलाना बहुत ज़्यादा हटा देता है — दर्द और इन्फेक्शन का ख़तरा। यूरिया वाली क्रीम रोज़ लगाना धीरे-धीरे, सुरक्षित रूप से नरम करती है।", "आज रात रूखी जगहों पर मोटी क्रीम लगाएं — रोज़ करें।", "घर पर ब्लेड या खुरचनी से कॉर्न हटाना।", "डायबिटीज़ हो तो रोज़ पैर जांचें और कॉर्न/घाव की देखभाल विशेषज्ञ से कराएं।"),
        "feet_7" to Hi("नंगे पैर की सावधानी", "साझा बाथरूम, पूल और जिम के लॉकर में चप्पल पहनें।", "गर्म-गीले साझा फ़र्श पर एथलीट फुट और नाखून के फंगस फैलते हैं। एक साधारण चप्पल एक सस्ती, असरदार दीवार है।", "अगली बार जिम/पूल जाते समय चप्पल बैग में रखें।", "साझा गीली जगहों पर नंगे पैर चलना।"),
        "feet_8" to Hi("हफ़्ते का पैर-रिचुअल", "भिगोएं, साफ़ करें, सुखाएं, मॉइस्चराइज़ करें — पैर इसके हक़दार हैं।", "10 मिनट गुनगुने (गर्म नहीं) पानी में पैर, तलवों की हल्की स्क्रब, ध्यान से सुखाई और अच्छी क्रीम — पैरों को आराम भी मिलता है और आपको रूसी, छिलने या नाखून के रंग जैसे बदलाव जल्दी दिखते हैं।", "इस वीकेंड 10 मिनट का पैर-स्पा और जांच करें।", "छिलती त्वचा या बदलते नाखून को नज़रअंदाज़ करना।", "उंगलियों के बीच छिलना-खुजली या गहरा-मोटा नाखून — फंगल हो सकता है; इलाज मौजूद है।"),

        // ---------------- UNDERARM ----------------
        "underarm_1" to Hi("अंडरआर्म की नरम सफ़ाई", "अंडरआर्म रोज़ एक बार नरम साबुन से धोएं।", "अंडरआर्म की त्वचा पतली और सिलवटदार है; वहाँ पसीना बैक्टीरिया से मिलकर बदबू बनाता है। माइल्ड धुलाई इसे बिना जलन के हटाती है — वहाँ की त्वचा बांह की त्वचा से ज़्यादा नाज़ुक है।", "आज अंडरआर्म को ठीक से, नरमी से धोएं।", "सख़्त साबुन और ज़ोर की रगड़।"),
        "underarm_2" to Hi("सूखी त्वचा पर डिओडरेंट", "डिओडरेंट पूरी तरह सूखी त्वचा पर लगाएं।", "डिओडरेंट और एंटीपरस्पिरेंट सूखी त्वचा पर सबसे अच्छी पकड़ रखते हैं। गीली त्वचा पर वह खिसक जाता है — कम असर और चिपचिपाहट। पहले पूरा थपथपाकर सुखाएं।", "अगली बार डिओडरेंट से पहले जगह को पूरा सुखाएं।", "नहाने के तुरंत बाद गीली त्वचा पर लगाना।"),
        "underarm_3" to Hi("नरम शेविंग", "तेज़ ब्लेड + शेविंग जेल से, बालों की दिशा में शेव करें।", "अंडरआर्म की त्वचा मुड़ी हुई और नाज़ुक है। ग्लाइड वाली (सूखी नहीं) और बालों की दिशा में शेविंग से जलन, रेज़र बंप और चोट कम होते हैं। स्ट्रोक के बीच ब्लेड धोते रहें।", "शेव करें तो जेल लगाकर नया ब्लेड इस्तेमाल करें; बाद में मॉइस्चराइज़ करें।", "सूखी शेविंग या डूल ब्लेड पर ज़ोर।", "दर्दनाक मवाद वाले दाने या न भरने वाली गांठ — डॉक्टर को दिखाएं।"),
        "underarm_4" to Hi("सांस लेने वाले कपड़े", "सूती जैसे नेचुरल फैब्रिक अंडरआर्म को हवा देते हैं — बदबू घटती है।", "टाइट सिंथेटिक कपड़े पसीने को त्वचा पर बांध देते हैं — बैक्टीरिया और जलन बढ़ती है। ढीले बुनान या नेचुरल फाइबर के ऊपरी कपड़े जगह को सूखा रखते हैं, गर्मी और वर्कआउट में ख़ासकर।", "कल के लिए सांस लेने वाला ऊपरी चुनें और फ़र्क़ देखें।", "वर्कआउट के बाद घंटों भीगा टॉप पहने रहना।"),
        "underarm_5" to Hi("डिओडरेंट बनाम एंटीपरस्पिरेंट", "डिओडरेंट बदबू से लड़ता है; एंटीपरस्पिरेंट पसीना घटाता है।", "डिओडरेंट बैक्टीरिया की बदबू को दबाता/बदलता है; एंटीपरस्पिरेंट में एल्युमिनियम लवण पसीने की नलियों को कुछ समय के लिए बंद रखते हैं। पसीना सामान्य-स्वस्थ है — एंटीपरस्पिरेंट बस गीलापन परेशान करे तब मदद करता है, रात साफ़-सूखी त्वचा पर लगाना सबसे असरदार है।", "आज पता करें आप जो इस्तेमाल करती हैं वह कौन-सा है और आपका मक़सद क्या है।", "डिओडरेंट से पसीना बंद होने की उम्मीद रखना।"),
        "underarm_6" to Hi("रात की छोटी रूटीन", "रात को साफ़-सूखा छोड़ दें: धोएं, सुखाएं, प्रोडक्ट मत लगाएं।", "रात भर बिना प्रोडक्ट की साफ़ त्वचा उसे सांस लेने और ठीक होने देती है, एंटीपरस्पिरेंट की जमाव भी घटाती है। और असल में एंटीपरस्पिरेंट रात में सबसे अच्छा चलता है — सोने से पहले साफ़ सूखी त्वचा पर।", "आज रात धोकर पूरा सुखाकर सोएं।", "दिन-दिन भर प्रोडक्ट के ऊपर प्रोडक्ट लगाते रहना।"),
        "underarm_7" to Hi("कालेपन के साथ न्याय", "अंडरआर्म का रंग हर किसी का अलग होता है; रगड़ और इरिटेशन उसे गहरा करते हैं।", "ज़्यादातर अंडरआर्म गहराई रगड़ (टाइट कपड़े), शेविंग की जलन या प्रोडक्ट रिएक्शन से आती है — सफ़ाई की कमी से नहीं। नरम आदतें उसे धीरे-धीरे हल्का करती हैं। यह आम, सामान्य त्वचा-भिन्नता है, कोई शर्म की बात नहीं।", "आज अपने कपड़ों में से वह चुनें जो वहाँ रगड़ खाता है।", "तेज़ ‘व्हाइटनिंग’ क्रीमों से और इरिटेशन बढ़ाना।", "अचानक खुजली वाला गहरापन, गांठ या दर्द — डॉक्टर से मिलें।"),
        "underarm_8" to Hi("पसीना सामान्य है", "पसीना शरीर का स्वस्थ काम है — मैनेज करना देखभाल है, लड़ाई नहीं।", "पसीना शरीर को ठंडा करता है। हर किसी का पसीना अलग मात्रा में आता है — गर्मी, तनाव और हार्मोन उसे रोज़ बदलते हैं। अच्छी हाइजीन से आराम से मैनेज हो जाता है; सामान्य शारीरिक प्रक्रिया को लेकर शर्म की कोई बात नहीं।", "आज नोट करें कब सबसे ज़्यादा पसीना आता है — शरीर अपना काम कर रहा है।", "सामान्य पसीने को ‘गंदगी’ समझना।"),

        // ---------------- GROOMING ----------------
        "grooming_1" to Hi("रोज़ की सिंपल ग्रूमिंग रूटीन", "सुबह के दस मुतमईन मिनट पूरे काम कर जाते हैं।", "फ्रेश होना, बाल, चेहरा, हाथ — एक साफ़ रूटीन स्क्रॉल करने से कम समय लेती है। रोज़ एक ही समय करने से यह बोझ नहीं, एक शांत रिचुअल बन जाती है — और पूरी आपकी है।", "आज सुबह की रूटीन का समय नापें और उसे 10 मिनट में सिमटाएं।", "हर सुबह 12-स्टेप भारी रूटीन ठान लेना।"),
        "grooming_2" to Hi("भौंहों की नरम देखभाल", "बाहर निकले बाल साफ़ करें; भौंह की नेचुरल लाइन न तोड़ें।", "ज़्यादा प्लक की गई भौंहें धीरे उगती हैं और समय के साथ पतली पड़ जाती हैं। नेचुरल लाइन से बाहर के साफ़ बाल हटाना — नहाने के बाद नरम त्वचा पर — शेप नेचुरल रखता है। एक बार प्रोफेशनल शेप, फिर घर पर मेंटेनेंस — अच्छा तरीका है।", "आज किसी भी तौलिये/पिंसेट को हाथ लगाने से पहले अपनी नेचुरल भौंह-लाइन देखें।", "भौंहों को पतली पतली लाइनों में बदल डालना।"),
        "grooming_3" to Hi("चेहर के बाल — आपकी मर्ज़ी", "हटाने के कई नरम तरीके हैं — जो आपकी त्वचा को सूट करे वही सही।", "चेहर के बाल पूरी तरह सामान्य हैं और उनके साथ क्या करना है — यह व्यक्तिगत पसंद है, ज़रूरत नहीं। ट्रिमिंग, थ्रेडिंग, वैक्स, डिपिलेटरी क्रीम (पहले पैच टेस्ट) या ऐसे ही छोड़ देना — सब ठीक है। जो भी करें, साफ़ औज़ार और बाद में नरम देखभाल ज़रूरी है।", "फेशियल हेयर हटाती हैं तो आज औज़ारों-प्रोडक्ट की सफ़ाई-एक्सपायरी जांच लें।", "रेज़र साझा करना या एक्सपायर क्रीम इस्तेमाल करना।"),
        "grooming_4" to Hi("कानों की देखभाल", "सिर्फ़ बाहरी कान साफ़ करें; कॉटन बड्स अंदर कभी नहीं।", "कान खुद साफ़ होते हैं — कान का मोम अपने आप बाहर आता है। बड्स अंदर घुसाने से मोम और भीतर धकेलता है और पर्दा रगड़ सकता है। बाहरी कान को नरम गीले कपड़े से पोंछना काफ़ी है।", "आज सिर्फ़ बाहरी कान साफ़ करें।", "कान के अंदर कॉटन बड्स ठूंसना।", "कान में दर्द, बहना या सुनने में कमी — डॉक्टर को दिखाएं।"),
        "grooming_5" to Hi("ग्रूमिंग टूल्स की हाइजीन", "पिंसेट, रेज़र, कैंची — साफ़, सूखी और सुरक्षित रखें।", "जो औज़ार त्वचा छूता है उस पर त्वचा के कण और बैक्टीरिया आते हैं। धोना, सुखाना, सूखी जगह रखना — और कभी-कभार अल्कोहल से पोंछना — औज़ार सुरक्षित और लंबे चलने वाले रहते हैं।", "आज अपने ग्रूमिंग टूल्स को अल्कोहल से पोंछ दें।", "गीली दराज में जंग लगे औज़ार रखना।"),
        "grooming_6" to Hi("इत्र को सही तरीके से", "कम ही ज़्यादा: मॉइस्चराइज़्ड पल्स पॉइंट पर हल्का स्प्रे।", "इत्र नम त्वचा पर ज़्यादा देर टिकता है और हल्का लगाया गया इत्र दिन भर खूब बदलते हुए अच्छा लगता है। ज़्यादा मारना कमरे में घुसते ही तेज़ पड़ता है; खुशबू बताई नहीं जाती, महसूस कराई जाती है।", "आज अपनी पसंद की खुशबू एक-दो पल्स पॉइंट पर ही लगाएं।", "लगाकर दोनों कलाइयां आपस में रगड़ना — खुशबू के नोट टूट जाते हैं।"),
        "grooming_7" to Hi("शाम की रीसेट", "रात के 5 मिनट की रूटीन कल की सुबह आसान बना देती है।", "दिन की मेकअप पूरी उतारना, दांत साफ़ करना और कल के कपड़े तैयार रखना — सुबह की भागदौड़ी छोटी कर देता है और दिन का अंत थकान से नहीं, देखभाल से होता है।", "आज रात पूरी मेकअप उतारकर, साफ़ होकर सोएं।", "मेकअप पहने सो जाना — घंटों के संपर्क में रोमछिद्र बंद होते हैं।"),
        "grooming_8" to Hi("ग्रूमिंग = देखभाल, न कि ‘सुधार’", "आप फ्रेश महसूस करने के लिए करती हैं — चेहरा ‘ठीक’ करने के लिए नहीं।", "ब्यूटी स्टैंडर्ड हर साल बदलते हैं; आपका चेहरा कोई समस्या नहीं जिसे solve करना हो। ग्रूमिंग को रख-रखाव और आत्म-सम्मान समझें (जिस चीज़ की आप कद्र करती हैं उसकी सर्विस) — तनाव नहीं, आनंद बनती है।", "कल की ग्रूमिंग के कदम इस लिए चुनें कि वे आपको अच्छा महसूस कराएं।", "शर्म या फ़िल्टर वाले चेहरों से तुलना करते हुए ग्रूम करना।"),

        // ---------------- MENSTRUAL ----------------
        "menstrual_1" to Hi("अपने साइकल को समझें", "सामान्य साइकल 21–35 दिन का होता है; पीरियड आमतौर पर 2–7 दिन।", "मासिक धर्म चक्र हार्मोन के बदलावों से चलता है जो शरीर को हर महीने तैयार करते हैं। साइकल हर किसी में अलग होते हैं — और महीने-महीने थोड़ा बदलना भी सामान्य है। ट्रैक करने से अगला पीरियड अंदाज़ा और अपने पैटर्न समझ आते हैं।", "आज से एक सिंपल नोट शुरू करें: पिछले पीरियड का पहला दिन लिख लें।", "हर छोटे बदलाव को लेकर घबराना।", "लगातार 21 दिन से छोटे, 35 से लंबे साइकल या बहुत भारी ब्लीडिंग — डॉक्टर से मिलें।"),
        "menstrual_2" to Hi("समय पर प्रोडक्ट बदलना", "पैड 4–6 घंटे में; टैम्पन 4–8 घंटे में — रातभर कभी नहीं।", "ताज़ा प्रोडक्ट बदबू, इरिटेशन और — टैम्पन बहुत देर रखने के दुर्लभ मामले में — गंभीर इन्फेक्शन से बचाता है। फ़ोन में एक शांत रिमाइंडर व्यस्त दिनों में भी याद रखाता है।", "आज अपने बदलने के अंतराल का रिमाइंडर सेट करें।", "एक ही टैम्पन को अधिकतम समय तक रोज़-रोज़ लगाए रखना।"),
        "menstrual_3" to Hi("पीरियड में धुलाई", "बाहरी हिस्से को दिन में एक-दो बार गुनगुने पानी से धोना काफ़ी है।", "योनि खुद साफ़ होती है; सिर्फ़ बाहरी हिस्से को गुनगुने पानी और चाहें तो माइल्ड बिना-खुशबू साबुन से धोएं। डाउचिंग या तेज़ इंटीमेट वॉश नेचुरल बैलेंस बिगाड़कर इन्फेक्शन कर सकते हैं।", "अगली बार बाथरूम में बाहरी धुलाई गुनगुने पानी से करें।", "अंदर पानी डालना (डाउचिंग) या खुशबूदार प्रोडक्ट इस्तेमाल करना।"),
        "menstrual_4" to Hi("डिस्पोज़ेबल बनाम रियूज़ेबल", "पैड, टैम्पन, कप और पीरियड अंडरवियर — सब ठीक इंतिखाब हैं।", "डिस्पोज़ेबल सुविधाजनक हैं; कप, कपड़े के पैड और पीरियड अंडरवियर लंबे समय में पैसे बचाते हैं और कचरा घटाते हैं। अहम बात सही इस्तेमाल और सफ़ाई है: रियूज़ेबल को निर्देश के मुताबिक़ धोना/सुखाना/स्टेरिलाइज़ करना।", "आज एक ऐसा प्रोडक्ट पढ़कर देखें जो आपने कभी आज़माया नहीं।", "कप या कपड़े के पैड को सिफ़त से ज़्यादा देर इस्तेमाल करते रहना।"),
        "menstrual_5" to Hi("दर्द में आराम", "गर्माई, हल्की मूवमेंट और आराम — आम क्रैम्प में सच में मदद करते हैं।", "पेट के निचले हिस्से पर हीट पैड, हल्की स्ट्रेचिंग या टहलना, पर्याप्त पानी और आराम — आम क्रैम्प में असर करते हैं। दर्द की गोली लें तो पैकेट के निर्देश के मुताबिक़, दर्द चरम पर पहुंचने से पहले लेना ज़्यादा असरदार होता है।", "क्रैम्प हो तो आज 15 मिनट गर्माई + हल्की स्ट्रेचिंग आज़माएं।", "बहुत तेज़ दर्द को ‘औरतों का हिस्सा’ समझकर बर्दाश्त करते रहना।", "दर्द से रोज़मर्रा के काम न हो पाएं तो डॉक्टर से ज़रूर मिलें — एंडोमेट्रियोसिस जैसी स्थितियों का इलाज मौजूद है।"),
        "menstrual_6" to Hi("फ्लो ट्रैकिंग", "फ्लो की मात्रा और लक्षण नोट करना बड़ा काम का रिकॉर्ड बनता है।", "अपने आम फ्लो (हल्का/मध्यम/भारी दिन), क्लॉट का आकार और लक्षण जानना प्लानिंग में मदद करता है और कभी डॉक्टर को ज़रूरी तो बहुत काम की जानकारी देता है। कोई भी नोट्स ऐप या कैलेंडर चलता है।", "आज अपने ट्रैकिंग में फ्लो और लक्षण भी जोड़ें।", "सब याददाश्त पर छोड़ देना — ज़रूरत पड़े तब याद नहीं रहता।"),
        "menstrual_7" to Hi("फ्रेश और आत्मविश्वासी रहना", "समय पर बदलना, सांस लेने वाले अंदरूनी और रोज़ की धुलाई — बस।", "अच्छी हाइजीन से पीरियड की बदबू बहुत कम और सामान्य होती है। ताज़ा सूती अंदरूनी, समय पर बदलाव और रोज़ धुलाई पूरा काम करते हैं — स्प्रे वाले वाइप्स नहीं चाहिए, वे जलन भी कर सकते हैं।", "पीरियड के दिनों में सांस लेने वाला सूती अंदरूनी पहनें।", "बदलने की जगह स्प्रे से बदबू छिपाना।"),
        "menstrual_8" to Hi("डॉक्टर से कब पूछें", "कुछ संकेत — बहुत भारी ब्लीडिंग, बर्दाश्त से बाहर दर्द — सलाह मांगने लायक हैं।", "हर घंटे पैड/टैम्पन भर देना, पीरियड के बीच में खून, रोज़मर्रा रोक देने वाला दर्द, या प्रेग्नेंसी की संभावना न होते हुए 3 महीने तक पीरियड रुकना — ये डॉक्टर से पूछने के संकेत हैं। जल्दी पूछना समझदारी है, ड्रामा नहीं।", "हाल में दिखे किसी असामान्य लक्षण का नोट बना लें।", "हर महीने बेहोश कर देने वाले दर्द को सामान्य मान लेना।", "भारी, दर्दनाक या बंद पीरियड — डॉक्टर/गायनोकोलॉजिस्ट जांच लें; असरदार इलाज हैं।"),

        // ---------------- SLEEP ----------------
        "sleep_1" to Hi("एक नियमित स्लीप विंडो", "रोज़ एक ही समय सोएं और उठें — शरीर की घड़ी इससे चलती है।", "शरीर की सर्केडियन घड़ी नियमितता से ताक़त पाती है। सोने-जागने का एक जैसा समय — वीकेंड पर भी एक घंटे के भीतर — नींद जल्दी आती है और उठना आसान होता है।", "आज रात एक तय बेड-टाइम रखें और कल उसी वक़्त का अलार्म लगाएं।", "हफ़्ते में 5 घंटे और वीकेंड पर 10 घंटे सोना।"),
        "sleep_2" to Hi("सोने से पहले का आख़िरी घंटा", "आख़िरी घंटा शांत रखें: धीमी रोशनी, कोई काम नहीं, कोई स्क्रॉलिंग नहीं।", "तेज़ स्क्रीन और उत्तेजक कंटेंट दिमाग़ को चौकन्ना रखते हैं और नींद का हार्मोन मेलाटोनिन देर से बनता है। रोशनी घटाना और कुछ शांत करना — पढ़ना, स्किन केयर, स्ट्रेचिंग — शरीर को बताता है कि रात शुरू हुई है।", "आज रात सोने से 30 मिनट पहले फ़ोन दूर रखें।", "बिस्तर में ‘नींद आएगी’ के लिए स्क्रॉल करना — उल्टा असर होता है।"),
        "sleep_3" to Hi("सोने का माहौल", "ठंडा, अंधेरा और शांत — नींद का आदर्श त्रिकोण।", "सोते समय शरीर का तापमान गिरता है; ठंडा कमरा (करीब 18°C) इसे साथ देता है। अंधेरा मेलाटोनिन बढ़ाता है और शांति (या स्थिर व्हाइट नॉइज़) उन छोटी जागन को रोकती है जो याद भी नहीं रहतीं।", "आज एक चीज़ ठीक करें: तापमान, पर्दा या आवाज़।", "गर्म-रोशन कमरे में रातभर टीवी चलाना।"),
        "sleep_4" to Hi("कैफ़ीन की समय-सीमा", "सोने से 6–8 घंटे पहले कैफ़ीन बंद कर दें।", "कैफ़ीन का आधा असर 5–6 घंटे तक रहता है — दोपहर की कॉफ़ी बेड-टाइम तक आधी चालू होती है; नींद आ भी जाए तो गहरी नहीं होती। चाय, कोला, एनर्जी ड्रिंक और चॉकलेट में भी कैफ़ीन छिपा होता है।", "आज आख़िरी कैफ़ीन दोपहर के शुरू से पहले ले लें।", "शाम को ‘मुझपर असर नहीं होता’ वाली कॉफ़ी।"),
        "sleep_5" to Hi("नींद और त्वचा", "त्वचा की मरम्मत ज़्यादातर गहरी नींद में होती है।", "गहरी नींद में त्वचा में खून का बहाव बढ़ता है और रिपेयर का काम चरम पर होता है। इसीलिए रात मेकअप उतारना, धोना और मॉइस्चराइज़ करना सच में असरदार है — साफ़, नम त्वचा नाइट-शिफ्ट का पूरा फ़ायदा उठाती है।", "आज रात पूरी क्लींज़िंग-मॉइस्चराइज़िंग करके सोएं।", "दिन की मेकअप-सनस्क्रीन पहने सो जाना।"),
        "sleep_6" to Hi("बिस्तर = नींद", "बिस्तर को नींद के लिए रखें — दिमाग़ को यह लिंक सिखाएं।", "बिस्तर में काम करना, खाना या घंटों स्क्रॉल करना दिमाग़ को सिखाता है कि बिस्तर = चौकन्नापन। बिस्तर को ज़्यादातर नींद के लिए रखने पर लेटते ही झपकी का संकेत बन जाता है।", "आज तबही बिस्तर में जाएं जब सोने को तैयार हों।", "लैपटॉप और ऑफ़िस का काम चादर में लेना।"),
        "sleep_7" to Hi("मददगार झपकियां", "झपकी लें तो दोपहर 3 बजे से पहले और 25 मिनट से कम।", "लंबी या देर शाम की नींद रात की नींद की भूख कम कर देती है — रात की नींद छिछली और टूटती है। छोटी-जल्दी वाली झपकी तरोताज़ा करती है बिना रात चुराए।", "आज थकान लगे तो दोपहर की छोटी 20-मिनट झपकी लें।", "शाम की 2 घंटे की नींद और फिर रात 1 बजे जागना।"),
        "sleep_8" to Hi("आधी रात जाग जाएं तो", "20 मिनट में नींद न आए तो उठ जाएं, कुछ शांत करें, फिर आएं।", "बिस्तर में बेचैनी से पड़े रहना दिमाग़ को बिस्तर = तनाव सिखाता है। उठकर धीमी रोशनी में कुछ पढ़ना जब तक ऊनी न आए, फिर लौटना — बिस्तर-नींद का रिश्ता बचा रहता है।", "आज रात जागें तो 20-मिनट वाला नियम आज़माएं।", "घड़ी देखकर ‘अब कितनी नींद बची’ गिनती करना।", "तेज़ खर्राटे के साथ दिनभर थकान — या हफ़्तों की बेनींदी — डॉक्टर से पूछने लायक है।"),

        // ---------------- NUTRITION ----------------
        "nutrition_1" to Hi("पानी की बुनियाद", "हल्के-पीले पेशाब को अपना पानी-मीटर मानें।", "पानी त्वचा की नमी, तापमान और ऊर्जा को सहारा देता है। प्यास देर से लगती है, इसलिए दिनभर घूंट-घूंट पीना रात की बाढ़ से बेहतर है। 6–8 गिलास एक आम सीमा है; गर्मी और मेहनत से ज़रूरत बदलती है।", "अभी एक बोतल भरें और दोपहर तक खाली करें; दोपहर में फिर भरें।", "कॉफ़ी और मीठे ड्रिंक को पानी गिनना।"),
        "nutrition_2" to Hi("त्वचा को पोषण", "रंगीन फल-सब्ज़ियां त्वचा को अंदर से खिलाती हैं।", "विटामिन C (नींबू, जामुन, शिमला मिर्च) कोलेजन बनाने में मदद करता है, विटामिन E (नट्स, बीज) कोशिकाओं की झिल्ली बचाता है और बीटा-कैरोटीन (गाजर, मिठ्ठा आलू) त्वचा की सेहत में योगदान देता है। कोई एक जादुई चीज़ नहीं — विविधता ही असली है।", "आज के खाने में एक रंगीन फल या सब्ज़ी जोड़ें।", "बुरा खाना खाते हुए महंगे सप्लीमेंट पी जाना।"),
        "nutrition_3" to Hi("प्रोटीन और बाल", "बाल ज़्यादातर प्रोटीन से बने हैं — पर्याप्त प्रोटीन सामान्य बढ़वे को सहारा देता है।", "बाल और नाखून केराटिन से बनते हैं जिसे शरीर खाने के प्रोटीन से बनाता है। लगातार बहुत कम प्रोटीन बालों के बढ़ने को धीमा कर सकता है। दाल, अंडा, दूध, चना, मछली-मांस — सब अच्छे स्रोत हैं।", "आज हर भोजन में एक प्रोटीन स्रोत रखें।", "एक ‘हेयर विटामिन’ से ग़लत खाने की भरपाई की उम्मीद।", "वज़न घटने या डाइट बदलने के साथ बाल झड़ना बढ़े तो डॉक्टर को बताएं।"),
        "nutrition_4" to Hi("चीनी और त्वचा", "बार-बार चीनी का उछाल कुछ लोगों में दाने बढ़ा सकता है।", "बार-बार तेज़ चीनी उछाल सूजन बढ़ा सकता है और तेल ग्रंथियों को प्रभावित कर सकता है; कुछ लोगों को मिठाई संभालने पर त्वचा साफ़ दिखती है। यह संतुलन की बात है — चीनी से दुश्मनी नहीं; असर हर किसी पर अलग होता है।", "आज एक मीठा स्नैक फल या नट्स से बदलें।", "एक चीज़ को ‘ज़हर’ बताकर डराना।"),
        "nutrition_5" to Hi("खाने का रिदम", "रोज़ के भोजन का नियमित समय ऊर्जा और त्वचा दोनों को भाता है।", "भोजन छोड़कर बाद में ज़्यादा खाने से ब्लड शुगर और ऊर्जा उछाल-गिरावट पर चलती है। लगभग नियमित समय शरीर को अनुमान देता है, बेहतर चुनाव करवाता है और देर रात का खाना घटाता है।", "आज दिन भागने से पहले तीनों भोजनों का समय तय कर लें।", "दिनभर कॉफ़ी पर चलकर आधी रात का ढेर सारा खाना।"),
        "nutrition_6" to Hi("आयरन और ऊर्जा", "कम आयरन महिलाओं में आम है — थकान और रंग-रूप पर दिखता है।", "पीरियड, प्रेग्नेंसी और खान-पान आयरन का स्तर गिरा सकते हैं — थकान, फीकी त्वचा और बाल झड़ना तक दिख सकता है। आयरन-रिच खाना (दालें, पालक, लाल मांस, फोर्टिफाइड अनाज) विटामिन C के साथ बेहतर सोखा जाता है।", "आज पौधे वाले आयरन को विटामिन C के साथ लें — जैसे दाल में नींबू।", "टेस्ट कराए बिना खुद ज़्यादा आयरन की गोली शुरू करना।", "लगातार थकान, सांस फूलना या भारी पीरियड — सरल खून की जांच करवाएं।"),
        "nutrition_7" to Hi("पेट और चमक", "फाइबर और किण्वित खाने पेट को सहारा देते हैं — जो सेहत से जुड़ा है।", "फाइबर-रिच डाइट (सब्ज़ियां, साबुत अनाज, दालें) और किण्वित खाना (दही, छाछ, इडली-डोसा का घांव) पेट के माइक्रोबायोम को संतुलित रखते हैं — जो इम्युनिटी और त्वचा से जुड़ा दिखता है।", "आज एक फाइबर-रिच और एक किण्वित खाना जोड़ें।", "‘डिटॉक्स’ चाय और कठोर क्लींज़ पर भरोसा।"),
        "nutrition_8" to Hi("कैफ़ीन का संतुलन", "कैफ़ीन का आनंद लें — बस अपनी सीमा और समय जानें।", "वयस्कों के लिए दिन में करीब 400 मीग्रा (करीब 3–4 कप कॉफ़ी) तक सुरक्षित माना जाता है। असली मुश्किलें हैं — देर शाम की कैफ़ीन नींद खराब करना और मीठी कॉफ़ी-ड्रिंक्स का छिपा शुगर।", "आज अपनी कैफ़ीन गिनें — चाय, कोला और एनर्जी ड्रिंक समेत।", "कोला-एनर्जी ड्रिंक को गिनना भूल जाना।"),

        // ---------------- FITNESS ----------------
        "fitness_1" to Hi("मूवमेंट स्नैक्स", "दिनभर के छोटे-छोटे मूवमेंट जमा होकर बड़ा फ़ायदा देते हैं।", "रिसर्च बताती है — 5–10 मिनट की टहलना, स्ट्रेच या सीढ़ियां असली सेहत का फ़ायदा जमा करती हैं; कई बार लंबे जिम सेशन से ज़्यादा बनती रहती हैं। हर कदम और स्ट्रेच गिना जाता है।", "आज 3 मूवमेंट अलार्म लगाएं: खड़े हों, स्ट्रेच करें या 5 मिनट टहलें।", "‘पूरा वर्कआउट नहीं हो सकता’ में पूरा दिन बैठे रह जाना।"),
        "fitness_2" to Hi("पोस्चर रीसेट", "दिन में कई बार कंधे पीछे घुमाएं और गर्दन खींचें।", "डेस्क और फ़ोन की घंटों झुकी बैठन से कंधे अगले और गर्दन पर बोझ पड़ता है। छोटे रीसेट — कंधे की धीमी गोलाई, ठुड्डी अंदर, 30 सेकंड लंबे खड़े होना — तनाव कम करते हैं और कद बेहतर करते हैं।", "अभी 10 धीमी कंधे-गोलाई और 5 ठुड्डी-इन करें।", "सही इर्गोनॉमिक चेयर का इंतज़ार करते हुए रोज़ झुके बैठना।"),
        "fitness_3" to Hi("टहलना — कम गिना जाने वाला ग्लो-अप", "20–30 मिनट की तेज़ टहल खून के बहाव, मूड और चेहरे की चमक तक बढ़ाती है।", "टहलना दिल की धड़कन नरमी से बढ़ाता है, त्वचा तक (हां, त्वचा तक भी) खून का बहाव बढ़ाता है, पाचन में मदद करता है और दिमाग़ साफ़ करता है। बाहर टहलें तो ताज़ी हवा और धूप भी — नींद और मूड के लिए अच्छी।", "आज 20 मिनट तेज़ टहलें — हो सके तो बाहर।", "‘टहलना गिनती में नहीं’ समझना।"),
        "fitness_4" to Hi("सबके लिए ताक़त", "हफ़्ते में दो बार ताक़त का काम हड्डियों, कद और मेटाबोलिज़्म को बचाए रखता है।", "मांसपेशियां और हड्डियां बोझ का जवाब देती हैं। सिंपल बॉडीवेट कसरत — स्क्वाट, दीवार पुश-अप, ब्रिज — हफ़्ते में 2–3 बार ताक़त और जोड़ों को सहारा रखती हैं; महिलाओं के लिए लंबे समय में हड्डियों की मज़बूती ख़ास अहम है।", "आज 10 स्क्वाट और 10 वॉल पुश-अप का एक सेट करें।", "‘भारी हो जाऊंगी’ का डर — हल्की वज़न से नहीं होता।"),
        "fitness_5" to Hi("स्ट्रेच और लचीलापन", "मूवमेंट के बाद 5 मिनट स्ट्रेच शरीर को लचीला रखता है।", "नरम स्ट्रेचिंग जोड़ों की गति बनाए रखती है और अकड़न घटाती है। गर्म मांसपेशियों पर — टहलने या नहाने के बाद — सबसे अच्छी लगती है। गर्दन, कंधे, कूल्हे और हैमस्ट्रिंग — ये रोज़ की जकड़ी जगहें हैं।", "आज टहलने/नहाने के बाद 5 मिनट स्ट्रेच करें।", "ठंडी मांसपेशियों पर झटके वाली, ज़ोर की स्ट्रेचिंग।"),
        "fitness_6" to Hi("वर्कआउट के बाद त्वचा", "पसीना धोना और भीगे कपड़े बदलना दानों से बचाता है।", "पसीना और वर्कआउट कपड़ों की रगड़ चेहरे, पीठ और छाती पर रोमछिद्र बंद और त्वचा चिढ़ सकती है। वर्कआउट के बाद जल्दी शावर या कम-से-कम चेहरा धोकर सूखे कपड़े पहनना त्वचा साफ़ रखता है।", "अगली बार वर्कआउट के 30 मिनट के भीतर कपड़े बदलें।", "घंटों भीगे जिम कपड़ों में बैठे रहना।"),
        "fitness_7" to Hi("आराम के दिन भी प्लान का हिस्सा", "रिकवरी में ही शरीर असल में मज़बूत बनता है।", "कसरत उत्तेजना है; आराम में मांसपेशियां रिपेयर होकर बढ़ती हैं। हफ़्ते में एक-दो आराम या हल्के-मूवमेंट वाले दिन बर्नआउट और चोट से बचाते हैं — नींद और मूड भी बेहतर रहते हैं।", "इस हफ़्ते प्लान बनाएं: कौन-से दिन मूवमेंट, कौन-से आराम के? ", "हर आराम के दिन को लेकर अपराध-बोध महसूस करना।"),
        "fitness_8" to Hi("साइकल के हिसाब से मूवमेंट", "अपनी ऊर्जा के हिसाब से कसरत की तीव्रता चुनना बिल्कुल ठीक है।", "कई महिलाओं को पीरियड के बाद के हफ़्तों में सबसे ज़्यादा ताक़त महसूस होती है और भारी/PMS दिनों में हल्की मूवमेंट (टहलना, योगा, स्ट्रेच) ज़्यादा सुहाती है। इन उतार-चढ़ाव को मानना — बिना बिल्कुल छोड़े — मूवमेंट को टिकाऊ बनाता है।", "आज अपनी ऊर्जा के हिसाब से मूवमेंट चुनें, अपराध-बोध के नहीं।", "थकी शरीर पर ज़बरदस्ती बहुत तेज़ वर्कआउट।", "कसरत में चक्कर, सीने में दर्द या असामान्य सांस फूलना — तुरंत रुककर डॉक्टर से मिलें।"),

        // ---------------- SELFCARE ----------------
        "selfcare_1" to Hi("सिर्फ़ आपके लिए दो मिनट", "रोज़ एक छोटी खिड़की चुनें जो पूरी तरह आपकी हो।", "सेल्फ-केयर के लिए स्पा-डे नहीं चाहिए। सुरक्षित पांच मिनट — चुपचाप चाय, एक गाना, स्ट्रेच, बाहर कदम — तनाव हार्मोन कम करते हैं और यह एहसास लौटाते हैं कि आपकी ज़रूरतें भी गिनती में हैं।", "आज के दिन में 5 मिनट ‘मेरे’ नाम कर दें।", "उस वीकेंड का इंतज़ार जो कभी नहीं आता।"),
        "selfcare_2" to Hi("मानसिक शावर", "शाम की धुलाई के साथ दिन का तनाव भी बहा दें।", "शारीरिक रिचुअल (चेहरा धोना) को मानसिक रिचुअल से जोड़ना (‘आज की चिंताएं बहा रही हूं’) एक सिंपल माइंडफुलनेस तकनीक है। रूटीन दिमाग़ के लिए दिन बंद करने का संकेत बन जाती है।", "आज रात क्लींज़िंग के समय तीन चीज़ें नाम लेकर छोड़ दें।", "बेड पर दिन के तनाव की रील चलाते रहना।"),
        "selfcare_3" to Hi("सांस = रीसेट बटन", "लंबी छोड़ी गई सांस एक मिनट में तंत्रिका तंत्र को शांत करती है।", "छोड़ती हुई सांस लंबी करना (अंदर 4, बाहर 6–8) ‘आराम’ प्रतिक्रिया चालू करता है — धड़कन धीमी, मांसपेशियां ढीली। यह इतनी सधी है कि कहीं भी की जा सकती है: बस, परीक्षा, तनाव वाली मीटिंग।", "अभी 6 बार: 4 पर अंदर, 8 पर बाहर।", "सिर्फ़ संकट के वक़्त गहरी सांस लेना — रोज़ का अभ्यास ही असर देता है।"),
        "selfcare_4" to Hi("डिजिटल हाइजीन", "अपनी फ़ीड को स्किन केयर की तरह समझें — जो चिढ़ाए, हटा दें।", "जो अकाउंट आपको अपने शरीर या त्वचा को लेकर बेकार महसूस कराते हैं वे तुलना-तनाव की रोज़ की बूंदें हैं। अनफ़ॉलो करना कमज़ोरी नहीं — ठीक वैसे ही जैसे जलने वाला प्रोडक्ट बंद करना।", "आज 3 अकाउंट अनफ़ॉलो/म्यूट करें जो ‘कम’ महसूस कराते हैं।", "एडिट किए चेहरों को ‘इन्स्पिरेशन’ बनाकर घंटों स्क्रॉल।"),
        "selfcare_5" to Hi("हल्की डायरी", "रोज़ तीन लाइन: एक जीत, एक एहसास, एक आभार।", "छोटी-सी डायरी आत्म-जागरूकता बनाती है बिना दबाव के। हफ़्तों में पैटर्न दिखते हैं — क्या उठाता है, क्या खींचता है — और यही जानकारी बेहतर सेल्फ-केयर चुनावों की बुनियाद है।", "आज रात सोने से पहले 3 लाइन लिखें।", "पेजों-पेज लिखने का ठानना और तीसरे दिन छोड़ देना।"),
        "selfcare_6" to Hi("‘ना’ कहना भी सेल्फ-केयर है", "अपनी ऊर्जा की रक्षा किसी फेस मास्क से कम नहीं।", "हर ‘हां’ समय और ऊर्जा का खर्च है। छोटे, नरम ‘ना’ (‘इस हफ़्ते ये नहीं ले सकती’) उस नाराज़गी और थकान को रोकते हैं जिसे कोई सीरम नहीं मिटाता।", "आज एक ग़ैर-ज़रूरी फ़र्ज़ या बुलावा नरमी से ठुकरा दें।", "हर चीज़ में हां कहकर वीकेंड पर ढह जाना।"),
        "selfcare_7" to Hi("शरीर-न्यूट्रल आभार", "शरीर को उसके काम के लिए धन्यवाद दें — रूप के लिए नहीं।", "पैर जो आपको लेकर चलते हैं, हाथ जो बनाते हैं, फेफड़े जो सांस लेते हैं — बॉडी-न्यूट्रैलिटी ध्यान को रूप से भूमिका पर लाती है; रिसर्च इसे रूप-केंद्रित सोच से बेहतर मूड और स्वस्थ आदतों से जोड़ती है।", "आज मन में एक शरीर-हिस्से को उसके काम के लिए धन्यवाद कहें।", "शीशे में खड़े होकर हर ‘कमी’ गिनना।"),
        "selfcare_8" to Hi("हफ़्ते का सेल्फ-केयर घंटा", "हफ़्ते में एक घंटा गहरी देखभाल पूरे हफ़्ते को रीसेट करता है।", "रोज़ के मिनटों के अलावा हफ़्ते का एक घंटा — हेयर मास्क, होम मेनीक्योर, लंबा नहाना, प्रकृति में टहल — एक छोटी मुलाक़ात बन जाता है जिसकी आप इंतज़ार करने लगती हैं और जिसे बचाती हैं।", "अभी अगले हफ़्ते में 1 घंटे की ‘अपना-समय’ अपॉइंटमेंट लिख दें।", "अपने ऊपर समय खर्च करने को स्वार्थ समझना।"),

        // ---------------- EVERYDAY ----------------
        "everyday_1" to Hi("60-सेकंड की सुबह", "धोएं/मॉइस्चराइज़ करें/SPF — और दौड़ लगाएं।", "पूरी सुबह की स्किन रूटीन सच में एक मिनट में हो सकती है: चुटकी धुलाई, मॉइस्चराइज़र, सनस्क्रीन। रोज़ किया गया यह न्यूनतम महीने में दो बार की भारी रूटीन से बेहतर है।", "कल सुबह की रूटीन का समय लगाएं — 60 सेकंड में आती है? ", "दस स्टेप का समय नहीं मिलने पर सब कुछ छोड़ देना।"),
        "everyday_2" to Hi("होंठों की देखभाल", "जीभ चाटने की जगह सादा लिप बाम।", "लार उड़कर होंठों को उससे भी ज़्यादा सुखा देती है — चाटने-फटने का चक्र बन जाता है। सादा बाम नमी सील कर देता है और कटे होंठ रातभर में भरने लगते हैं — सोने से पहले लगाना जादुई है।", "आज रात लिप बाम बिस्तर के पास रखें और लगाएं।", "सर्दी-सूखे में बार-बार होंठ चाटना।"),
        "everyday_3" to Hi("हैंड क्रीम की आदत", "हैंड क्रीम वहीं रखें जहां इस्तेमाल होगा — बेड या ताश के पास।", "हाथ दिन में कई बार धोए जाते हैं और उम्र-रूखापन सबसे पहले वहीं दिखता है। हर धुलाई के बाद और सोने से पहले मटर-जितनी क्रीम हाथों को आराम और नाखूनों को मज़बूती देती है।", "हैंड क्रीम को आज नज़र वाली जगह रखें और हर धुलाई के बाद लगाएं।", "तीन क्रीम खरीदकर तीनों दूर की दराज में रखना।"),
        "everyday_4" to Hi("आंखों के आसपास की नरमी", "आई मेकअप नरमी से उतारें — वहां की त्वचा शरीर की सबसे पतली है।", "आंखों के आसपास ज़ोर से रगड़ने से नाज़ुक त्वचा खिंचती है और आंखें चिढ़ती हैं। मेकअप रिमूवर या नरम क्लींज़र को पलक पर कुछ सेकंड दबाकर रखें और रगड़े बिना पोंछ लें।", "आज रात आई मेकअप दबाकर-पोंछकर उतारें, रगड़े बिना।", "वॉटरप्रूफ मस्कारा को खुरदरे वाइप से रगड़ना।"),
        "everyday_5" to Hi("धुलाई के बीच बाल फ्रेश करना", "स्कैल्प रिफ्रेश, हिस्सा बदलना या चोटी — बिना धुलाए अच्छा बाल-दिन।", "धुलाइयों के बीच हल्का स्कैल्प रिफ्रेश (या बस हिस्सा बदलना, चोटी, क्लिप स्टाइल) बालों को जीवित कर देता है। ‘फ्लैट’ दूसरे दिन के बालों को ठीक करने के लिए रोज़ धोना या रोज़ हीट पहनाना उल्टा असर करता है।", "आज बिना धुले फ्रेश करें: हिस्सा बदलें, चोटी या क्लिप।", "फ्रेशनेस के लिए रोज़ ऊंची गर्मी का फ्लैट-आयरन।"),
        "everyday_6" to Hi("खुशबू की तहें", "सुगंधित लोशन + ऊपर हल्का इत्र — अकेले स्प्रे से ज़्यादा देर टिकता है।", "सूखी त्वचा से इत्र के अणु जल्दी उड़ते हैं। नीचे (मैचिंग या बिना-खुशबू) लोशन की तह और ऊपर इत्र — खुशबू का दायरा घंटों चलता है, कम प्रोडक्ट में।", "आज इत्र से पहले मॉइस्चराइज़ करें।", "नाक थक जाने पर बार-बार स्प्रे करते रहना।"),
        "everyday_7" to Hi("शीशे से दोस्ताना बात", "खुद से वैसे बात करें जैसे किसी दोस्त से करतीं।", "शीशे के सामने आत्म-आलोचना मूड और मोटिवेशन मापती है — उदासीन या दोस्ताना स्व-बात उल्टा असर देती है। रोज़ एक दोस्ताना वाक्य समय के साथ अपने साथ रिश्ता बदल देता है।", "आज शीशे में अपने साथ एक मीठा वाक्य बोलें।", "शीशे के सामने ‘ठीक करने’ की लिस्ट पढ़ना।"),
        "everyday_8" to Hi("रात का एक-मिनट रीसेट", "साठ सेकंड की टिडाई कल की सुबह को शांत करती है।", "कपड़े हैम्पर में, मेज़ साफ़, बोतल भरी — कल रात के साठ सेकंड सुबह की साफ़-शांत शुरुआत खरीद लेते हैं। माहौल और मन एक-दूसरे को खिलाते हैं।", "आज रात किसी एक कोने का 60-सेकंड रीसेट करें।", "हफ़्ते भर का ढेर वीकेंड पर मिटाने की ज़िद।")
    )

    fun localize(tip: Tip): Tip = tip.copy(
        title = title(tip.id) ?: tip.title,
        short = short(tip.id) ?: tip.short,
        detail = detail(tip.id) ?: tip.detail,
        action = action(tip.id) ?: tip.action,
        mistake = mistake(tip.id) ?: tip.mistake,
        safety = safety(tip.id) ?: tip.safety
    )
}
